package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDeserializerFactory;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.AnnotationIntrospector;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_constructSettableProperty_TriageGen0Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanPropertyDefinition propDef;
    private JavaType propType;

    // Test target class to provide mutators
    static class TestBean {
        public String name;
        public void setName(String name) {} // Method mutator
        public int age;
        public void setAge(int age) {}     // Method mutator
    }

    static class FieldBean {
        @JsonProperty("field")
        public String field; // Field mutator
    }

    @Before
    public void setUp() {
        factory = new BeanDeserializerFactory(DeserializerFactoryConfig.NO_CONFIG);
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        propDef = mock(BeanPropertyDefinition.class);
        propType = mock(JavaType.class);

        // Default behavior for beanDesc
        when(beanDesc.getClassAnnotations()).thenReturn(AnnotationIntrospector.noop());
    }

    /**
     * Test Case 1: Test Method Mutator (AnnotatedMethod)
     */
    @Test
    public void testConstructSettableProperty_MethodMutator() throws Exception {
        // Setup Method Mutator
        AnnotatedMethod mutator = mock(AnnotatedMethod.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);

        // Mock resolving type
        JavaType resolvedType = mock(JavaType.class);
        when(propType.getTypeHandler()).thenReturn(null);
        // We need to override the protected method resolveMemberAndTypeAnnotations 
        // Since we can't easily override protected in a mock, we rely on the fact that 
        // in a real environment, this calls internal logic. 
        // For unit testing a protected method in the same package, we use a spy.

        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(resolvedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());
        when(resolvedType.getValueHandler()).thenReturn(null);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertTrue(result instanceof MethodProperty);
    }

    /**
     * Test Case 2: Test Field Mutator (AnnotatedField)
     */
    @Test
    public void testConstructSettableProperty_FieldMutator() throws Exception {
        AnnotatedField mutator = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);

        JavaType resolvedType = mock(JavaType.class);
        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(resolvedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        when(resolvedType.getValueHandler()).thenReturn(null);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertTrue(result instanceof FieldProperty);
    }

    /**
     * Test Case 3: Test Bad Property Definition (No mutator)
     */
    @Test(expected = JsonMappingException.class)
    public void testConstructSettableProperty_NoMutatorThrowsException() throws Exception {
        when(propDef.getNonConstructorMutator()).thenReturn(null);

        factory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        verify(ctxt).reportBadPropertyDefinition(eq(beanDesc), eq(propDef), contains("No non-constructor mutator available"));
    }

    /**
     * Test Case 4: Test Deserializer Contextualization and Annotation Deserializer
     */
    @Test
    public void testConstructSettableProperty_WithDeserializer() throws Exception {
        AnnotatedMethod mutator = mock(AnnotatedMethod.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);

        JavaType resolvedType = mock(JavaType.class);
        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(resolvedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        // Mock finding deserializer from annotation
        JsonDeserializer<?> annotatedDeser = mock(JsonDeserializer.class);
        doReturn(annotatedDeser).when(spyFactory).findDeserializerFromAnnotation(ctxt, mutator);

        // Mock contextualization
        JsonDeserializer<?> contextualizedDeser = mock(JsonDeserializer.class);
        when(ctxt.handlePrimaryContextualization(eq(annotatedDeser), any(), eq(resolvedType)))
                .thenReturn(contextualizedDeser);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertEquals(contextualizedDeser, result.getValueDeserializer());
    }

    /**
     * Test Case 5: Test Managed Reference Property
     */
    @Test
    public void testConstructSettableProperty_ManagedReference() throws Exception {
        AnnotatedMethod mutator = mock(AnnotatedMethod.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);

        JavaType resolvedType = mock(JavaType.class);
        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(resolvedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        // Setup Reference
        AnnotationIntrospector.ReferenceProperty ref = mock(AnnotationIntrospector.ReferenceProperty.class);
        when(ref.isManagedReference()).thenReturn(true);
        when(ref.getName()).thenReturn("myRef");
        when(propDef.findReferenceType()).thenReturn(ref);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertEquals("myRef", result.getManagedReferenceName());
    }

    /**
     * Test Case 6: Test ObjectIdInfo
     */
    @Test
    public void testConstructSettableProperty_ObjectIdInfo() throws Exception {
        AnnotatedMethod mutator = mock(AnnotatedMethod.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);

        JavaType resolvedType = mock(JavaType.class);
        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(resolvedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(propDef.findObjectIdInfo()).thenReturn(objectIdInfo);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertEquals(objectIdInfo, result.getObjectIdInfo());
    }

    /**
     * Test Case 7: Test fallback to type's value handler when annotation deser is null
     */
    @Test
    public void testConstructSettableProperty_FallbackToValueHandler() throws Exception {
        AnnotatedMethod mutator = mock(AnnotatedMethod.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);

        JavaType resolvedType = mock(JavaType.class);
        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(resolvedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        JsonDeserializer<?> valueHandler = mock(JsonDeserializer.class);
        when(spyFactory.findDeserializerFromAnnotation(ctxt, mutator)).thenReturn(null);
        when(resolvedType.getValueHandler()).thenReturn(valueHandler);

        // Mock contextualization for the value handler
        when(ctxt.handlePrimaryContextualization(eq(valueHandler), any(), eq(resolvedType)))
                .thenReturn(valueHandler);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertEquals(valueHandler, result.getValueDeserializer());
    }
}
